  "tour.terminal.new.body": "\u53EF\u6309\u9700\u6253\u5F00\u591A\u4E2A\u7EC8\u7AEF\uFF1B\u9690\u85CF\u9762\u677F\u540E\u5B83\u4EEC\u7EE7\u7EED\u8FD0\u884C\u3002",
