  "tour.terminal.split.body": "\u5728\u5F53\u524D\u7EC8\u7AEF\u65C1\u518D\u5F00\u4E00\u4E2A\uFF1B\u62D6\u52A8\u4E2D\u95F4\u7684\u5206\u9694\u6761\u8C03\u6574\u5BBD\u5EA6\u3002",
  "tour.terminal.more.body": "\u66F4\u591A\u64CD\u4F5C\uFF1A\u5206\u5C4F\uFF08\u624B\u673A\u4E0A\u4E0A\u4E0B\u5806\u53E0\uFF09\u548C\u5173\u95ED\u7EC8\u7AEF\u3002",
