  "tour.terminal.target.body": "\u663E\u793A\u7EC8\u7AEF\u6240\u5C5E\u7684\u8BBE\u5907\u548C\u5DE5\u4F5C\u533A\u3002\u5206\u5C4F\u4F1A\u8BDD\u65F6\uFF0C\u5B83\u8DDF\u968F\u5F53\u524D\u805A\u7126\u7684\u4E00\u4FA7\u3002",
