  "tour.terminal.touch.body": "\u70B9\u6309\u7EC8\u7AEF\u5373\u53EF\u8F93\u5165\uFF0C\u8F6F\u952E\u76D8\u5F39\u51FA\u65F6\u9762\u677F\u4F1A\u4FDD\u6301\u5728\u952E\u76D8\u4E0A\u65B9\u3002\u8FD9\u6392\u6309\u952E\u8865\u5145 Ctrl\u3001Esc\u3001Tab \u548C\u65B9\u5411\u952E\uFF1B\u8FD4\u56DE\u624B\u52BF\u6536\u8D77\u9762\u677F\u3002",
