  "tour.terminal.hide.body": "\u9690\u85CF\u9762\u677F\uFF0CShell \u7EE7\u7EED\u8FD0\u884C\u3002\u518D\u70B9\u7EC8\u7AEF\u6309\u94AE\u5373\u53EF\u56DE\u6765\u3002",
  "tour.split.trigger.title": "\u6253\u5F00\u7B2C\u4E8C\u4E2A\u4F1A\u8BDD",
  "tour.split.trigger.body": "\u5728\u5F53\u524D\u5BF9\u8BDD\u65C1\u5E76\u6392\u663E\u793A\u53E6\u4E00\u4E2A\u5BF9\u8BDD\uFF0C\u4FBF\u4E8E\u5BF9\u7167\u6216\u534F\u4F5C\u3002",
  "tour.split.picker.title": "\u9009\u62E9\u5BF9\u8BDD",
  "tour.split.picker.body": "\u5148\u5217\u51FA\u540C\u4E00\u5DE5\u4F5C\u533A\u7684\u5BF9\u8BDD\uFF0C\u5176\u6B21\u662F\u672C\u8BBE\u5907\u7684\u5176\u4ED6\u5DE5\u4F5C\u533A\uFF1BRelay \u4E0B\u8FD8\u4F1A\u5217\u51FA\u5176\u4ED6\u8BBE\u5907\u3002\u6309 \u8BBE\u5907 \u2192 \u5DE5\u4F5C\u533A \u2192 \u5BF9\u8BDD \u9010\u7EA7\u8FDB\u5165\uFF0C\u300C\u8FD4\u56DE\u4E0A\u4E00\u7EA7\u300D\u56DE\u5230\u4E0A\u4E00\u5C42\u3002",
  "tour.split.picker.prereq": "\u5148\u70B9\u51FB\u300C\u4F1A\u8BDD\u5206\u5C4F\u300D\u6253\u5F00\u9009\u62E9\u5668\u3002",
  "tour.split.panes.title": "\u4E24\u4FA7\u90FD\u53EF\u64CD\u4F5C",
  "tour.split.panes.body": "\u4E24\u4E2A\u4F1A\u8BDD\u90FD\u80FD\u76F4\u63A5\u8F93\u5165\u548C\u64CD\u4F5C\u3002\u70B9\u51FB\u54EA\u4E00\u4FA7\uFF0C\u54EA\u4E00\u4FA7\u5C31\u83B7\u5F97\u7126\u70B9\u3002",
  "tour.split.panes.prereq": "\u5728\u5206\u5C4F\u9009\u62E9\u5668\u91CC\u9009\u4E00\u4E2A\u5BF9\u8BDD\u540E\u7EE7\u7EED\u3002",
  "tour.split.mobile.body": "\u624B\u673A\u4E0A\u4E00\u6B21\u663E\u793A\u4E00\u4FA7\uFF0C\u5728\u8FD9\u91CC\u5207\u6362\u4E24\u4E2A\u4F1A\u8BDD\u3002",
  "tour.split.focus.title": "\u5DE5\u5177\u8DDF\u968F\u7126\u70B9",
  "tour.split.focus.body": "\u7EC8\u7AEF\u548C\u6587\u4EF6\u6D4F\u89C8\u5668\u4F5C\u7528\u4E8E\u83B7\u5F97\u7126\u70B9\u90A3\u4E00\u4FA7\u7684\u5DE5\u4F5C\u533A\u3002\u300C\u8BBE\u4E3A\u4E3B\u4F1A\u8BDD\u300D\u4EA4\u6362\u4E24\u4FA7\uFF0C\u2715 \u5173\u95ED\u5206\u5C4F\u3002",
  "tour.files.open.title": "\u6253\u5F00\u6587\u4EF6",
  "tour.files.open.body": "\u4E0D\u79BB\u5F00\u5BF9\u8BDD\u5373\u53EF\u6D4F\u89C8\u5F53\u524D\u5DE5\u4F5C\u533A\u3002",
  "tour.files.needsDrawer": "\u5148\u7528\u9AD8\u4EAE\u7684\u6309\u94AE\u6253\u5F00\u6587\u4EF6\u6D4F\u89C8\u5668\u3002",
  "tour.files.tree.title": "\u5C55\u5F00\u76EE\u5F55",
  "tour.files.tree.body": "\u70B9\u51FB\u6587\u4EF6\u5939\u524D\u7684\u7BAD\u5934\uFF08\u6216\u53CC\u51FB\u3001\u952E\u76D8 \u2192\uFF09\u5C55\u5F00\u76EE\u5F55\uFF0C\u70B9\u51FB\u6587\u4EF6\u5373\u53EF\u9884\u89C8\u3002",
  "tour.files.filter.title": "\u641C\u7D22",
  "tour.files.filter.body": "\u6309\u540D\u79F0\u7B5B\u9009\uFF0C\u6216\u5728\u4FDD\u7559\u5B8C\u6574\u76EE\u5F55\u6811\u7684\u540C\u65F6\u9AD8\u4EAE\u5339\u914D\u9879\u3002",
  "tour.files.newFile.title": "\u65B0\u5EFA\u6587\u4EF6",
  "tour.files.newFile.body": "\u8F93\u5165\u76F8\u5BF9\u8DEF\u5F84\uFF08\u53EF\u5305\u542B\u5B50\u76EE\u5F55\uFF09\u540E\u521B\u5EFA\u3002\u53EA\u8BFB\u5DE5\u4F5C\u533A\u4E0D\u663E\u793A\u6B64\u6309\u94AE\u3002",
  "tour.files.newFile.prereq": "\u8FD9\u4E2A\u5DE5\u4F5C\u533A\u662F\u53EA\u8BFB\u7684\uFF0C\u56E0\u6B64\u6CA1\u6709\u300C\u65B0\u5EFA\u6587\u4EF6\u300D\u3002",
  "tour.files.edit.title": "\u9884\u89C8\u4E0E\u7F16\u8F91",
  "tour.files.edit.body": "\u70B9\u51FB\u300C\u7F16\u8F91\u6587\u4EF6\u300D\u6253\u5F00\u7F16\u8F91\u5668\uFF0C\u4FEE\u6539\u540E\u300C\u4FDD\u5B58\u6587\u4EF6\u300D\u6216\u300C\u53D6\u6D88\u7F16\u8F91\u300D\u3002",
  "tour.files.edit.prereq": "\u5148\u5728\u76EE\u5F55\u6811\u4E2D\u6253\u5F00\u4E00\u4E2A\u6587\u672C\u6587\u4EF6\u3002",
  "tour.files.save.title": "\u5B89\u5168\u4FDD\u5B58",
  "tour.files.save.body": "\u4FDD\u5B58\u524D\u4F1A\u5148\u6838\u5BF9\u78C1\u76D8\u7248\u672C\u3002\u82E5\u6587\u4EF6\u5DF2\u88AB Agent \u6216\u5176\u4ED6\u7A0B\u5E8F\u4FEE\u6539\uFF0C\u4F1A\u63D0\u793A\u51B2\u7A81\uFF1A\u53EF\u4FDD\u7559\u8349\u7A3F\u7EE7\u7EED\u7F16\u8F91\u3001\u91C7\u7528\u78C1\u76D8\u7248\u672C\u3001\u7528\u8349\u7A3F\u8986\u76D6\u6216\u4E0B\u8F7D\u78C1\u76D8\u5FEB\u7167\uFF0C\u7EDD\u4E0D\u9759\u9ED8\u8986\u76D6\u3002",
  "tour.files.close.title": "\u5173\u95ED\u6587\u4EF6",
  "tour.files.close.body": "\u56DE\u5230\u5BF9\u8BDD\u3002\u6709\u672A\u4FDD\u5B58\u7684\u4FEE\u6539\u65F6\u4F1A\u5148\u8BE2\u95EE\u3002",
  "tour.more.automation.title": "\u81EA\u52A8\u5316\uFF08\u53EA\u8BFB\uFF09",
  "tour.more.automation.body": "\u67E5\u770B Agent \u901A\u8FC7 CLI/API \u521B\u5EFA\u7684\u8BA1\u5212\u4E0E\u89E6\u53D1\u5668\u53CA\u5176\u7528\u91CF\u3002\u81EA\u52A8\u5316\u7531 Agent \u7BA1\u7406\uFF0C\u8FD9\u91CC\u53EA\u663E\u793A\u72B6\u6001\u3002",
  "tour.more.subagents.title": "\u5B50\u667A\u80FD\u4F53",
  "tour.more.subagents.body": "\u5217\u51FA\u672C\u5BF9\u8BDD\u542F\u52A8\u7684\u5B50\u667A\u80FD\u4F53\u53CA\u5176\u8FD0\u884C\u72B6\u6001\u3002",
  "tour.more.subagents.prereq": "Agent \u542F\u52A8\u5B50\u667A\u80FD\u4F53\u540E\u4F1A\u51FA\u73B0\u5728\u8FD9\u91CC\uFF1B\u5B83\u4EEC\u7684\u5BF9\u8BDD\u4E5F\u4F1A\u5F52\u5728\u4FA7\u680F\u7684\u7236\u5BF9\u8BDD\u4E0B\u3002"
